#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum CampaignHarnessRoute {
    NativeReadQuestion,
    AgentHost,
    RuntimeDebugging,
    RuntimeDebuggingVisual,
}

impl CampaignHarnessRoute {
    pub(crate) fn for_task(task_id: &str) -> Result<Self, String> {
        let task = benchmark_task(task_id)
            .ok_or_else(|| format!("unknown benchmark task `{task_id}`"))?;
        Ok(match task.kind {
            BenchmarkTaskKind::ReadQuestion => Self::NativeReadQuestion,
            BenchmarkTaskKind::ProjectInspection
            | BenchmarkTaskKind::CodeImplementation
            | BenchmarkTaskKind::TypedAuthoringMutation
            | BenchmarkTaskKind::ValidationRepair => Self::AgentHost,
            BenchmarkTaskKind::RuntimeInteraction => Self::RuntimeDebugging,
            BenchmarkTaskKind::VisualEvaluation => Self::RuntimeDebuggingVisual,
        })
    }

    pub(crate) const fn requires_runtime_debugging(self) -> bool {
        matches!(self, Self::RuntimeDebugging | Self::RuntimeDebuggingVisual)
    }
}

