#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct CampaignFixtureWorkspace {
    pub(crate) candidate_project: PathBuf,
    pub(crate) visible_contract: PathBuf,
    host_evaluator_root: PathBuf,
    hidden_oracle: PathBuf,
}

impl CampaignFixtureWorkspace {
    pub(crate) fn host_evaluator_root(&self) -> &Path {
        &self.host_evaluator_root
    }

    pub(crate) fn hidden_oracle(&self) -> &Path {
        &self.hidden_oracle
    }
}

impl CampaignFixtureStore {
    pub(crate) fn open(root: PathBuf) -> Result<Self, String> {
        fs::create_dir_all(&root).map_err(|error| error.to_string())?;
        Ok(Self { root })
    }

    pub(crate) fn reset_for_run(
        &self,
        campaign_id: &str,
        schedule: &CampaignScheduleEntry,
        fixture: &CampaignFixtureIdentity,
    ) -> Result<CampaignFixtureWorkspace, String> {
        if !valid_campaign_id(campaign_id) {
            return Err("invalid campaign id for fixture materialization".to_owned());
        }
        let run_root = self.root.join(campaign_id).join(format!(
            "run-{:06}-{}",
            schedule.ordinal, fixture.instance_id
        ));
        if run_root.exists() {
            fs::remove_dir_all(&run_root).map_err(|error| error.to_string())?;
        }
        fs::create_dir_all(&run_root).map_err(|error| error.to_string())?;

        let candidate_project = run_root.join("candidate");
        create_standard_project(&candidate_project, "BenchmarkFixture")
            .map_err(|error| error.to_string())?;
        let contract = fixture.candidate_contract(&schedule.task_id)?;
        let visible_contract = candidate_project.join("benchmark-task.json");
        let visible_bytes =
            serde_json::to_vec_pretty(&contract).map_err(|error| error.to_string())?;
        fs::write(&visible_contract, visible_bytes).map_err(|error| error.to_string())?;

        let evaluator = fixture.host_evaluator(&schedule.task_id)?;
        let host_evaluator_root = run_root.join("host-evaluator");
        fs::create_dir_all(&host_evaluator_root).map_err(|error| error.to_string())?;
        let hidden_oracle = host_evaluator_root.join("oracle.json");
        let oracle = serde_json::json!({
            "task_id": evaluator.task_id,
            "hidden_token": evaluator.hidden_token,
            "fixture_instance_id": fixture.instance_id,
        });
        let oracle_bytes =
            serde_json::to_vec_pretty(&oracle).map_err(|error| error.to_string())?;
        fs::write(&hidden_oracle, oracle_bytes).map_err(|error| error.to_string())?;

        if hidden_oracle.starts_with(&candidate_project) {
            return Err("host-only evaluator must remain outside the candidate project root".to_owned());
        }
        Ok(CampaignFixtureWorkspace {
            candidate_project,
            visible_contract,
            host_evaluator_root,
            hidden_oracle,
        })
    }
}

